            new['death_date'] = author['death_date']
        return new
    a = {'type': {'key': '/type/author'}}
    for f in (
        'name',
        'title',
        'personal_name',
        'birth_date',
        'death_date',
        'date',
        'remote_ids',
    ):
        if f in author:
            a[f] = author[f]
    return a


