    def __init__(self, site, key, data=None, revision=None):
        self._site = site
        self.key = key
        self._revision = revision

        assert data is None or isinstance(data, dict)

        self._data = data
        self._backreferences = None

        # no back-references for embeddable objects
        if self.key is None:
            self._backreferences = {}

    def __hash__(self):
        if self.key:
            return hash(self.key)
        else:
            d = self.dict()
            # dict is not hashable and converting it to tuple of items isn't #
            # enough as values might again be dictionaries. The simplest
            # solution seems to be converting it to JSON.
            return hash(json.dumps(d, sort_keys=True))

    def _getdata(self):
        if self._data is None:
            self._data = self._site._load(self.key, self._revision)

            # @@ Hack: change class based on type
            self.__class__ = _thing_class_registry.get(
                self._data.get('type').key, Thing
            )

        return self._data

    def _get_backreferences(self):
        if self._backreferences is None:
            self._backreferences = self._site._get_backreferences(self)
        return self._backreferences

    def _get_defaults(self):
        return {}

    def keys(self):
        special = ['id', 'revision', 'latest_revision', 'last_modified', 'created']
        return [k for k in self._getdata() if k not in special]

    def get(self, key, default=None):
        try:
            return self._getdata()[key]
        except KeyError:
            # try default-value
            d = self._get_defaults()
            try:
                return d[key]
            except KeyError:
                if 'type' not in self._data:
                    return default
                return self._get_backreferences().get(key, default)

    def __getitem__(self, key):
        return self.get(key, nothing)

    def __setitem__(self, key, value):
        self._getdata()[key] = value

    def __setattr__(self, key, value):
        if key == '__class__':
            object.__setattr__(self, '__class__', value)
        elif key.startswith('_') or key in (
            'key',
            'revision',
            'latest_revision',
            'last_modified',
            'created',
        ):
            self.__dict__[key] = value
        else:
            self._getdata()[key] = value

class Thing(client.Thing):
    """Base class for all OL models."""

    key: ThingKey

    @cache.method_memoize
    def get_history_preview(self):
        """Returns history preview."""
        history = self._get_history_preview()
        history = web.storage(history)

        history.revision = self.revision
        history.lastest_revision = self.revision
        history.created = self.created

        def process(v):
            """Converts entries in version dict into objects."""
            v = web.storage(v)
            v.created = parse_datetime(v.created)
            v.author = v.author and self._site.get(v.author, lazy=True)
            return v

        history.initial = [process(v) for v in history.initial]
        history.recent = [process(v) for v in history.recent]

        return history

    @cache.memoize(engine="memcache", key=lambda self: ("d" + self.key, "h"))
    def _get_history_preview(self):
        h = {}
        if self.revision < 5:
            h['recent'] = self._get_versions(limit=5)
            h['initial'] = h['recent'][-1:]
            h['recent'] = h['recent'][:-1]
        else:
            h['initial'] = self._get_versions(limit=1, offset=self.revision - 1)
            h['recent'] = self._get_versions(limit=4)
        return h

    def _get_versions(self, limit, offset=0):
        q = {"key": self.key, "limit": limit, "offset": offset}
        versions = self._site.versions(q)
        for v in versions:
            v.created = v.created.isoformat()
            v.author = v.author and v.author.key

            # XXX-Anand: hack to avoid too big data to be stored in memcache.
            # v.changes is not used and it contrinutes to memcache bloat in a big way.
            v.changes = '[]'

